@media (max-width: 768px) {
    :root {
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
        --spacing-2xl: 2.5rem;
    }

    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .header-container {
        padding: 0 var(--spacing-md);
    }

    .nav-toggle {
        display: flex;
    }

    nav {
        position: fixed;
        top: 0;
        right: 0;
        height: 100vh;
        width: min(78vw, 320px);
        max-width: 320px;
        background: #fff;
        flex-direction: column;
        align-items: flex-start;
        justify-content: flex-start;
        gap: var(--spacing-lg);
        padding: 6rem var(--spacing-lg) var(--spacing-lg);
        box-shadow: -8px 0 24px rgba(0, 0, 0, 0.12);
        transform: translateX(100%);
        transition: transform 0.3s ease;
        z-index: 1050;
        overflow-y: auto;
    }

    nav.is-open {
        transform: translateX(0);
    }

    .nav-links {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--spacing-md);
        width: 100%;
    }

    nav a {
        font-size: 1.05rem;
    }

    .nav-cta {
        margin-left: 0;
        width: 100%;
        text-align: center;
    }

    .nav-backdrop {
        display: none;
        position: fixed;
        inset: 0;
        background: rgba(15, 23, 42, 0.45);
        z-index: 999;
    }

    .nav-backdrop.is-open {
        display: block;
    }

    .hero-container {
        padding: var(--spacing-lg);
    }

    .hero-content h1 {
        font-size: 1.8rem;
    }

    .destinations-grid {
        grid-template-columns: 1fr;
    }

    .pillars-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .footer-bottom {
        flex-direction: column;
        text-align: center;
    }
}

@media (max-width: 480px) {
    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .btn {
        padding: 0.75rem 1.25rem;
        font-size: 0.9rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .hero-cta {
        flex-direction: column;
        width: 100%;
    }

    .hero-cta .btn {
        width: 100%;
        justify-content: center;
    }

    .stats-grid {
        grid-template-columns: 1fr;
    }

    .stat-item h3 {
        font-size: 2rem;
    }
}

/* ==================== AFFILIATE / TRAVEL PLANNER UI ==================== */
.destination-actions {
    display: flex;
    gap: 0.65rem;
    margin-top: 1.15rem;
    flex-wrap: wrap;
}

.destination-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.7rem 1rem;
    border-radius: 0.65rem;
    border: 1px solid var(--primary);
    background: var(--primary);
    color: #fff;
    font-weight: 700;
    font-size: 0.82rem;
    text-decoration: none;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.destination-btn:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.destination-btn.secondary {
    background: transparent;
    color: var(--primary);
}

.planning-section {
    padding: var(--spacing-3xl) 0;
    background: #F5F3EE;
}

.planning-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-lg);
    margin-top: var(--spacing-2xl);
}

.planning-card {
    background: #fff;
    border: 1px solid var(--border);
    border-radius: 1rem;
    padding: var(--spacing-xl);
    box-shadow: var(--shadow-sm);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.planning-card:hover {
    transform: translateY(-3px);
    box-shadow: var(--shadow-md);
}

.planning-icon {
    font-size: 2rem;
    margin-bottom: 0.75rem;
}

.planning-card h3 {
    margin-bottom: 0.5rem;
}

.planning-card p {
    color: var(--text-secondary);
    line-height: 1.65;
    margin-bottom: 1rem;
}

.planner-cta {
    margin-top: var(--spacing-2xl);
    background: var(--dark);
    color: #fff;
