html.jl-rtl .jl-language-menu button{text-align:right}
@media (min-width:769px){
  #primaryNav{display:flex;align-items:center;gap:clamp(18px,2.2vw,34px)}
  #primaryNav .nav-links{gap:clamp(26px,3vw,46px)}
  #primaryNav .nav-cta{margin-left:0}
}
@media (max-width:768px){
  .header-actions{gap:8px}
  .jl-language{margin-left:0}
  .jl-language-trigger{min-width:0;padding:0 10px;height:40px}
}
@media (max-width:400px){
  .jl-language-code{display:none}
  .jl-language-trigger{padding:0 8px;gap:4px}
}
.jl-language-menu-header{display:none}
.jl-language-backdrop{position:fixed;inset:0;background:rgba(15,23,42,.45);opacity:0;visibility:hidden;transition:opacity .2s ease,visibility .2s ease;z-index:1150}
.jl-language-backdrop.is-visible{opacity:1;visibility:visible}
@media (max-width:768px){
  .jl-language-menu{
    position:fixed!important;left:0!important;right:0!important;bottom:0!important;top:auto!important;
    width:100%!important;max-width:none!important;margin:0!important;
    max-height:75vh;overflow-y:auto;-webkit-overflow-scrolling:touch;
    border-radius:20px 20px 0 0!important;padding:10px 14px 24px!important;
    box-shadow:0 -8px 30px rgba(15,23,42,.25)!important;
    transform:translateY(100%)!important;
    transition:transform .25s ease,opacity .25s ease,visibility .25s ease!important;
    z-index:1201;
  }
  .jl-language.is-open .jl-language-menu{transform:translateY(0)!important}
  .jl-language-menu-header{display:flex;align-items:center;justify-content:space-between;padding:10px 6px 14px;margin-bottom:6px;border-bottom:1px solid rgba(15,118,110,.14);font:700 16px/1 inherit;color:#153b3a}
  .jl-language-close{border:0;background:#eef8f7;color:#08756f;width:32px;height:32px;border-radius:50%;font-size:20px;line-height:1;cursor:pointer;flex:0 0 auto}
  .jl-language-menu button{padding:15px 12px;font-size:16px;min-height:48px}
  html.jl-rtl .jl-language-menu{left:0!important;right:0!important}
}
