  function handleNewsletter(event) {
            event.preventDefault();
            const email = event.target.querySelector('input[type="email"]').value;
            alert(`Thank you for subscribing with ${email}! Check your inbox for welcome email.`);
            event.target.reset();
        }

        // Header-aware same-page navigation
        // The header is sticky, so native scrollIntoView() can place a section
        // underneath it. Calculate the live header height before every jump.
        function scrollToSection(id) {
            const target = document.getElementById(id);
            const header = document.querySelector('header');
            if (!target) return;

            const headerHeight = header ? header.getBoundingClientRect().height : 0;
            const gap = 18;
            const targetTop = target.getBoundingClientRect().top + window.pageYOffset;

            window.scrollTo({
                top: Math.max(0, targetTop - headerHeight - gap),
                behavior: 'smooth'
            });
        }

        window.scrollToSection = scrollToSection;

        // Intercept internal anchors before older handlers so every section
        // uses the same sticky-header offset.
        document.addEventListener('click', function (e) {
            const link = e.target.closest('a[href^="#"]');
            if (!link) return;
            const href = link.getAttribute('href');
            if (!href || href === '#' || href === '#terms-and-conditions') return;

            const id = href.slice(1);
            if (!document.getElementById(id)) return;

            e.preventDefault();
            scrollToSection(id);
        }, true);

        // Mobile hamburger menu
        const navToggle = document.querySelector('.nav-toggle');
        const primaryNav = document.getElementById('primaryNav');
        const navBackdrop = document.getElementById('navBackdrop');

        function closeNav() {
            if (!primaryNav) return;
            primaryNav.classList.remove('is-open');
            if (navBackdrop) navBackdrop.classList.remove('is-open');
            if (navToggle) navToggle.setAttribute('aria-expanded', 'false');
            document.body.style.overflow = '';
        }

        function openNav() {
            if (!primaryNav) return;
            primaryNav.classList.add('is-open');
            if (navBackdrop) navBackdrop.classList.add('is-open');
            if (navToggle) navToggle.setAttribute('aria-expanded', 'true');
            document.body.style.overflow = 'hidden';
        }

        if (navToggle && primaryNav) {
            navToggle.addEventListener('click', function () {
                const isOpen = primaryNav.classList.contains('is-open');
                isOpen ? closeNav() : openNav();
            });
            if (navBackdrop) navBackdrop.addEventListener('click', closeNav);
            primaryNav.querySelectorAll('a, button').forEach(el => {
                if (el.closest('.jl-language')) return; // language switcher manages its own open/close state
                el.addEventListener('click', closeNav);
            });
            primaryNav.querySelectorAll('.jl-language-menu button[data-lang]').forEach(el => {
                el.addEventListener('click', closeNav); // still close the mobile menu once a language is actually picked
            });
            window.addEventListener('resize', function () {
                if (window.innerWidth > 768) closeNav();
            });
        }

        // Add scroll animation to destination cards
        const observerOptions = {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.style.animation = 'fadeInUp 0.6s ease forwards';
                }
            });
        }, observerOptions);

        document.querySelectorAll('.destination-card, .pillar-card').forEach(el => {
            el.style.opacity = '0';
            observer.observe(el);
        });

        // Add animation keyframe
        const style = document.createElement('style');
        style.textContent = `
            @keyframes fadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(20px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }
        `;
        document.head.appendChild(style);
    </script>
